    pub fn new(
        messages: Vec<IndexMap<String, MessageContent>>,
        images: Vec<DynamicImage>,
        videos: Vec<VideoInput>,
    ) -> Self {
        Self {
            messages,
            images,
            videos,
            last_accessed: Instant::now(),
